mapper.select:
SELECT r.reservation_id,r.user_id,COALESCE(t.name, l.name, st.name) AS userName,s.staff_id,s.name AS staffName,r.time,r.location FROM reservation r JOIN staff s ON r.staff_id = s.staff_id LEFT JOIN teacher t ON r.user_id = t.teacher_id LEFT JOIN logistics l ON r.user_id = l.logistics_id LEFT JOIN student st ON r.user_id = st.student_id
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

SELECT r.reservation_id,r.user_id,COALESCE(t.name, l.name, st.name) AS userName,s.staff_id,s.name AS staffName,r.time,r.location FROM reservation r JOIN staff s ON r.staff_id = s.staff_id LEFT JOIN teacher t ON r.user_id = t.teacher_id LEFT JOIN logistics l ON r.user_id = l.logistics_id LEFT JOIN student st ON r.user_id = st.student_id WHERE r.reservation_id like CONCAT('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

